        "code": {
          "text": "Fluid intake"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Drinking okay."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-7",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-7",
        "status": "final",
        "code": {
          "text": "Urinary symptoms"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Denies dysuria, frequency, urgency, haematuria, and flank pain."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-8",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-8",
        "status": "final",
        "code": {
          "text": "Vaginal bleeding or discharge"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "No per-vaginal bleeding or discharge reported."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-9",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-9",
        "status": "final",
        "code": {
          "text": "Last menstrual period and usual cycle"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Last menstrual period approximately 10 days ago. Cycles usually regular every 28–30 days and not usually heavy or painful."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-10",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-10",
        "status": "final",
        "code": {
          "text": "Patient-reported pregnancy possibility"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Unsure about pregnancy; does not think she is pregnant but says it is possible."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-11",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-11",
        "status": "final",
        "code": {
          "text": "Systemic symptoms"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "No fevers, rigors, weight loss, night sweats, chest pain, shortness of breath, recent gastroenteritis, or travel reported."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-12",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-12",
        "status": "final",
        "code": {
          "text": "Temperature"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueQuantity": {
          "value": 36.8,
          "unit": "°C"
        }
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-13",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-13",
        "status": "final",
        "code": {
          "text": "General appearance and breathing by telephone"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Limited telehealth assessment: sounds well on the phone, speaking in full sentences, with no shortness of breath."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-14",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-14",
        "status": "final",
        "code": {
          "text": "Self-palpation of abdomen"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Reports mild peri-umbilical and left iliac fossa tenderness; no focal severe right iliac fossa pain and no rebound or guarding by her description."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-15",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-15",
        "status": "final",
        "code": {
          "text": "Pain with hopping on one leg"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Able to hop on one leg without significant pain."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-16",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-16",
        "status": "final",
        "code": {
          "text": "Reported distension, jaundice, or rash"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "No obvious distension, jaundice, or rash reported."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-17",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-17",
        "status": "final",
        "code": {
          "text": "Health-related anxiety"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Very anxious about appendicitis or 'something bursting'; reports repeatedly googling symptoms. Previously saw a psychologist for exposure therapy, which helped, but stopped due to cost and availability."
      }
    },
    {
      "fullUrl": "https://example.org/fhir/Observation/observation-18",
      "resource": {
        "resourceType": "Observation",
        "id": "observation-18",
        "status": "final",
        "code": {
          "text": "Panic attacks, suicidality, and self-harm"
        },
        "subject": {
          "reference": "Patient/patient-1"
        },
        "valueString": "Denies panic attacks, suicidality, and self-harm."
      }
    },
